from itertools import product
from typing import Callable, Hashable, Optional, Tuple

State = Hashable
Symbol = Hashable

def single_word_dfa(word: Tuple[int, ...]):
    n = len(word); dead = n + 1
    def step(s: int, a: int) -> int:
        if s == dead: return dead
        if s < n and a == word[s]: return s + 1
        return dead
    return n + 2, (0, 1), step, 0, frozenset({n})

def search(num_states, alphabet, step, start, accept, lo, hi):
    def ev(w):
        s = start
        for a in w: s = step(s, a)
        return s
    for L in range(lo, hi):
        for w in product(alphabet, repeat=L):
            if ev(w) in accept: return w
    return None

if __name__ == '__main__':
    ns, alph, step, start, acc = single_word_dfa((1, 0, 1))
    ne = search(ns, alph, step, start, acc, 0, ns)
    inf = search(ns, alph, step, start, acc, ns, 2 * ns)
    print('nonempty witness:', ne)      # -> (1, 0, 1)
    print('infinite witness:', inf)     # -> None (language is finite!)

